QUESTIONS.push(
  X('backend','JVM','JVM 运行时内存区域有哪些？','线程私有的程序计数器、虚拟机栈和本地方法栈；线程共享的堆和方法区/元空间，直接内存则在堆外。',['堆存对象并由 GC 管理；栈帧包含局部变量表、操作数栈、动态链接和返回信息。','Metaspace 使用本地内存保存类元数据，仍可能因类加载器泄漏而 OOM。','OOM 日志要区分 Java heap space、Metaspace、Direct buffer memory 和 unable to create native thread。'],['对象一定分配在堆上吗？','StackOverflowError 如何产生？','直接内存怎么释放？'],'Java 平台开发的基础排障题。','简单',['JVM内存','OOM'],'必背'),
  X('backend','JVM','JVM 垃圾回收如何判断对象存活？','主流 JVM 从 GC Roots 做可达性分析；不可达对象才成为回收候选，而不是简单使用引用计数。',['GC Roots 包括线程栈引用、静态字段、JNI 引用和 JVM 内部对象。','强、软、弱、虚引用影响可达后的保留语义；SoftReference 不适合作为可预测缓存策略。','对象不可达后还涉及引用处理、Finalizer/Cleaner 和分代回收时机。'],['循环引用为什么能回收？','finalize 为什么弃用？','什么是 Safepoint？'],'用于理解长运行 Java 服务的内存泄漏。','中等',['GC Roots','可达性'],'必背'),
  X('backend','JVM','常见 GC 算法和 G1、ZGC 的取舍是什么？','标记-清除会产生碎片，复制算法适合存活率低区域，标记-整理消除碎片；G1 按 Region 回收，ZGC 追求极低停顿。',['分代假设让新对象频繁回收、老对象低频回收；晋升失败和大对象会影响停顿。','G1 根据预测收益选择 Region 做 Mixed GC，以目标停顿为软目标。','ZGC 使用并发标记/重定位和染色指针，低停顿但仍需关注吞吐、内存余量和版本。'],['Minor/Major/Full GC 区别？','为什么会 Stop-The-World？','如何选择 GC？'],'后端性能调优不能只背收集器名称。','困难',['GC','G1','ZGC'],'深挖'),
  X('backend','Java集合','HashMap 的结构、扩容和线程安全问题是什么？','Java HashMap 用数组桶加链表/红黑树，按哈希定位桶；超过负载阈值扩容，非线程安全。',['容量通常为 2 的幂，通过高低位扰动和位运算定位桶；负载因子默认 0.75。','冲突链达到阈值且容量足够时树化，减少恶劣冲突下查询退化。','并发读写可能丢失更新或看到不一致状态，应使用 ConcurrentHashMap 或外部同步。'],['为什么容量是 2 的幂？','红黑树何时退化回链表？','key 可变有什么风险？'],'Java 高频集合面经题。','中等',['HashMap','扩容'],'必背'),
  X('backend','Java并发','synchronized、volatile 和 Atomic 类有什么区别？','synchronized 提供互斥与可见性；volatile 提供可见性和有序性但不保证复合操作原子；Atomic 类用 CAS 实现无锁原子更新。',['`volatile++` 仍是读改写三步，会丢失更新。','synchronized 进入/退出建立 happens-before；现代 JVM 会做锁消除、粗化等优化。','CAS 可能有 ABA、忙等和高竞争失败，可使用版本戳、LongAdder 或锁。'],['DCL 为什么需要 volatile？','LongAdder 为什么更快？','CAS 是无锁还是无等待？'],'并发 Worker 计数、状态标志和共享表更新常见。','中等',['synchronized','volatile','CAS'],'必背'),
  X('backend','Spring','IoC/DI 和 AOP 分别解决什么问题？','IoC 容器负责对象创建与依赖装配，降低组件耦合；AOP 在连接点统一织入日志、事务、鉴权等横切逻辑。',['优先构造器注入，使依赖显式且便于测试；避免全局 Service Locator。','Spring AOP 通常基于代理，内部 self-invocation 可能绕过代理增强。','AOP 适合横切关注点，不应隐藏核心业务流程或制造难追踪控制流。'],['Bean 生命周期是什么？','JDK 动态代理和 CGLIB 区别？','循环依赖怎么产生？'],'Java 后端岗位常见基础框架题。','简单',['Spring','IoC','AOP'],'常规'),
  X('backend','Spring','@Transactional 为什么有时不生效？','常见原因包括同类内部调用绕过代理、方法不可代理、异常被吞、回滚规则不匹配或切换到另一个线程。',['默认通常只对 RuntimeException/Error 回滚，受检异常需显式 rollbackFor。','事务上下文绑定当前线程，异步任务不会自动继承。','传播行为、隔离级别和数据库实际能力必须一致，注解不能解决外部服务副作用。'],['REQUIRED 和 REQUIRES_NEW 区别？','private 方法能加事务吗？','事务中能否发消息？'],'可联系 Outbox 与“Agent 调用不能放数据库事务内”。','困难',['Spring事务','代理'],'深挖'),
  X('backend','Python','Python 的 GIL 是什么，影响哪些场景？','CPython GIL 让同一进程同一时刻通常只有一个线程执行 Python 字节码；I/O 阻塞或 C 扩展释放 GIL 时线程仍可并发。',['CPU 密集纯 Python 可用多进程、原生扩展或其他解释器；I/O 密集线程仍常有效。','GIL 不等于程序线程安全，复合操作、共享容器与外部状态仍需同步。','多进程有序列化、内存和启动成本；模型与大数据可考虑共享内存。'],['GIL 为什么存在？','Python 3.13 free-threaded 是什么？','asyncio 是否绕过 GIL？'],'Harness 主要使用 Python，必须能解释子进程与异步 I/O 选型。','简单',['Python','GIL'],'必背'),
  X('backend','Python','asyncio 的事件循环、Task 与 await 如何工作？','事件循环运行就绪回调和协程；await 在等待异步操作时让出控制权，Task 把协程调度为可并发推进的对象。',['异步适合大量 I/O 等待，不会自动加速 CPU 密集计算。','在事件循环里调用阻塞函数会卡住所有 Task，应使用异步库或线程/进程执行器。','取消通过 CancelledError 协作传播；finally 中清理资源，结构化并发避免孤儿 Task。'],['Coroutine 和 Task 区别？','gather 与 TaskGroup 区别？','如何设置总体超时？'],'直接对应并发读取 Runner stdout/stderr 与网络 Provider。','中等',['asyncio','事件循环'],'必背'),
  X('backend','Python','迭代器、生成器和 yield 的关系是什么？','迭代器实现迭代协议，生成器是由含 yield 的函数产生的惰性迭代器，可暂停并保存执行状态。',['惰性计算节省内存，适合流式日志、分页和管道处理。','`yield from` 可委托子迭代器；send/throw/close 能与生成器双向交互，但复杂协程优先 async/await。','生成器只可消费一次，异常和资源释放要在迭代终止时正确处理。'],['Iterable 与 Iterator 区别？','生成器如何关闭文件？','为什么列表推导可能占内存？'],'用于 Agent Event 和大 Artifact 的流式处理。','简单',['生成器','迭代器'],'常规'),
  X('backend','Python','Python 的浅拷贝、深拷贝和可变默认参数陷阱是什么？','浅拷贝只复制外层容器并共享内部对象，深拷贝递归复制；默认参数在函数定义时创建，使用可变对象会跨调用共享。',['使用 `None` 作为默认值并在函数内新建列表/字典。','赋值只是绑定同一对象，不是拷贝；切片与 copy.copy 通常是浅拷贝。','深拷贝可能昂贵且不适合文件、锁、Session 等外部资源对象。'],['闭包 late binding 是什么？','is 和 == 区别？','不可变对象需要深拷贝吗？'],'Python 基础面试与状态对象 bug 高频。','简单',['Python对象模型','拷贝'],'常规'),
  X('backend','Git','git merge、rebase 和 cherry-pick 有什么区别？','merge 合并历史并保留分叉，rebase 重放提交形成线性历史，cherry-pick 把选定提交复制到当前分支。',['已共享的公共提交不应随意 rebase/force push，避免改写他人历史。','冲突解决后要运行测试；rebase 中每个提交都可能单独冲突。','cherry-pick 会产生新提交哈希，后续再次合并需注意重复语义。'],['merge --no-ff 有什么用？','rebase --onto 怎么用？','如何撤销 rebase？'],'Git Worktree 与多 Agent 变更管理基础。','简单',['Git','merge','rebase'],'必背'),
  X('backend','Git','git reset、revert 和 restore 的区别是什么？','reset 移动分支/HEAD 并可修改暂存区和工作区；revert 新建反向提交，适合公共历史；restore 恢复文件内容。',['soft/mixed/hard 决定是否保留暂存与工作区，hard 会丢未提交修改。','公共分支撤销用 revert 可审计；revert merge commit 需要指定 mainline。','误删提交可通过 reflog 找回，只要对象尚未被 GC。'],['checkout 与 restore/switch 区别？','如何撤销已 push 提交？','reflog 保存多久？'],'Agent 自动 Git 操作必须避免破坏用户工作区。','中等',['Git reset','revert'],'必背'),
  X('backend','软件设计','SOLID 原则分别强调什么？','单一职责、开闭、里氏替换、接口隔离和依赖倒置共同帮助控制变化与耦合，但不是机械规则。',['单一职责指一个模块有一个主要变化原因，不等于每个类只一个方法。','开闭通过抽象和扩展点应对确定变化，不应为假想需求过度设计。','依赖倒置让高层策略依赖稳定接口，Adapter 是典型应用。'],['组合为什么常优于继承？','里氏替换如何判断？','SOLID 会不会增加复杂度？'],'Workflow-Harness 的 Runner Adapter 与 AV/Runtime 分层可作实例。','中等',['SOLID','软件设计'],'常规'),
  X('backend','设计模式','工厂、策略、适配器、观察者模式分别适合什么？','工厂封装创建，策略封装可替换算法，适配器统一不兼容接口，观察者把状态变化通知多个订阅者。',['模式解决重复设计问题，不应为了“用了模式”增加层级。','策略适合 Runner/模型路由；Adapter 统一 CLI 能力；观察者适合 Event/Trace，但要处理顺序与失败。','工厂负责构造不负责长期业务流程，复杂生命周期可由容器管理。'],['策略与状态模式区别？','观察者如何防内存泄漏？','Adapter 与 Facade 区别？'],'可直接用个人 Harness 项目回答，而非背定义。','简单',['设计模式','Adapter','Strategy'],'常规'),
  X('backend','编译链接','从 C/C++ 源码到可执行文件经历什么？','预处理展开宏和头文件，编译生成汇编，汇编生成目标文件，链接器解析符号与重定位生成可执行文件。',['静态链接把依赖代码复制进制品，体积大但部署独立；动态链接运行时加载共享库。','链接错误常来自符号未定义、重复定义、ABI 或链接顺序。','调试信息、优化级别、PIE 和 Sanitizer 选项会改变二进制行为与可观测性。'],['声明和定义区别？','ELF 里有哪些段？','动态库如何查找？'],'简历包含 C/C++、Fuzzing 与 Sanitizer，基础链路必须熟悉。','中等',['编译','链接','ELF'],'必背'),
  X('backend','调试','程序 Crash 后如何系统排查？','先保留环境、输入、版本、日志和 core dump，再定位信号/异常、线程栈、寄存器、内存与最近变更，构造最小稳定复现。',['Linux 用 ulimit/coredumpctl 获取 core，gdb 查看 bt、线程、局部变量和反汇编。','启用符号和 ASan/UBSan 可提高定位质量，但要保留原始构建复现。','区分根因 Crash、二次 Crash 和环境问题；修复后用原输入与相邻变体回归。'],['SIGSEGV 常见原因？','优化构建为何难调？','如何分析多线程死锁 core？'],'漏洞验证与 Runner/工具崩溃分类都需要。','中等',['GDB','Core Dump','Crash'],'必背'),
  X('backend','构建系统','Make/CMake 解决什么问题，增量构建为什么可能出错？','Make 按依赖与时间戳执行规则，CMake 生成跨平台构建系统；依赖声明不完整或生成文件未建模会产生错误缓存。',['Header、编译选项、环境变量和生成代码都必须进入依赖图或缓存键。','Out-of-source build 隔离产物；并行构建要求规则不共享未声明临时文件。','CI 应记录编译器、依赖、flags 和容器镜像，保证问题可复现。'],['make -j 为什么暴露竞态？','CMake target-based 写法优势？','如何做可复现构建？'],'Agent 自动构建真实仓库时常遇到的 Environment Failure。','中等',['Make','CMake','构建'],'常规')
);

// ── AdaptiveVuls V1.36：严格以 av.md（2026-07-29）为准 ──────────────
QUESTIONS.push(
  X('adaptivevuls','V1.36实现','V1.36 的三个 lane 是并行多 Agent 吗？','不是。三个 lane 表示权限与视角边界，主循环顺序执行，同一时刻最多运行一个 Coding-Agent 会话。',['Portfolio Controller 每次决策使用 Fresh Session，只选 Action Board 中的下一项。','Case Investigator 在同一 Case Revision 内 Sticky；Revision 或 Branch 后开启新会话。','Fresh Reviewer 每个 Evidence Checkpoint 使用 Fresh Session；Capability Advisor 是本地 JavaScript sidecar，不是第四个 Worker。'],['为什么顺序执行仍需要三个 lane？','能否未来并行多个 Case？','Reporter 是否是第四个科学主体？'],'这是新简历与 av.md 的当前实现事实，不能再表述成并行多 Agent 流水线。','简单',['V1.36','三个主体','顺序执行'],'必背'),
  X('adaptivevuls','Action Board','Eligible Action Board 包含什么，review_pending_checkpoint 为什么不在里面？','Board 是当前状态下合法的 Portfolio 候选动作空间；Review 是 Investigation Checkpoint 后不可跳过的协议延续。',['Board 至少包含 refresh_discovery、explore_frontier、form_case、investigate_case、acquire_deciding_artifact。','每个 Action 绑定 subject、trigger state、可选 Obligation 和重复指纹，它不是固定任务队列。','Reviewed Delta 提交后 Runtime 重建 Board，再由 Fresh Controller 选择。'],['Board 由谁构建？','如何防重复选择同一 Action？','Board Delta 如何审计？'],'V1.36 控制平面的核心对象。','困难',['Action Board','协议'],'高压'),
  X('adaptivevuls','发现机制','Action Board 为空时 AV 为什么执行 refresh_discovery？','当前无候选只说明没有已知可执行方向，不等于目标安全或攻击面覆盖；AV 用最新状态重新综合未覆盖安全关系。',['refresh_discovery 使用最新 Security Map、Reviewed Negative Knowledge、已处置 Case 和未覆盖攻击面。','只有外部墙钟或用户停止结束审计；Portfolio 收敛没有“目标安全”的科学含义。','Frontier 未产出新 grounded Object 时记录精确 Action 后回到 discovery，不伪造 revision 维持循环。'],['会不会形成无限循环？','Negative Knowledge 如何减少重复？','什么时候 Frontier 重开？'],'防止把“当前没事可做”误写成“已审计安全”。','困难',['refresh_discovery','探索'],'深挖'),
  X('adaptivevuls','Checkpoint','什么才算 Meaningful Evidence Checkpoint？','只有 Claim 实质变化、解释被区分、需要 Revision/Branch、产生新 Object、形成明确 Obligation、科学饱和或真实阻塞时才交接 Review。',['读文件、工具运行、测试通过或产生更多日志本身不是 Checkpoint。','Investigator 可以在一次 Sticky Session 内多次修正实验、增加 control 和追踪调用链。','所有解释标记为 UNREVIEWED INVESTIGATOR PROPOSAL，Investigator 不输出 Recommend Report。'],['谁决定 Checkpoint 到达？','Operational blocker 怎么记录？','为什么不限制 Artifact 数量？'],'用于解释 AV 不机械切 Episode 的原因。','中等',['Evidence Checkpoint','Investigator'],'必背'),
  X('adaptivevuls','Fresh Review','Fresh Reviewer 的输入为什么要把 Investigator Proposal 放最后？','先看权威 Case/OES 和原始 Artifact，后看 Investigator 叙事，可以减少被既有结论锚定。',['Reviewer 先独立回答 Artifact 观察、测试覆盖层、攻击者 baseline、增量能力、反事实、Boundary 与 Ownership。','Reviewer 选择 local_update、continue、revise、branch、merge 或 terminal。','如果引入新 attacker/root cause/Boundary/Ownership/impact family，必须 revise/branch + continue，新 Claim 初始 unknown，不能同轮报告。'],['Scope 窄化后能否同轮报告？','Reviewer 能否运行补充实验？','为什么 Fresh 仍可能失败？'],'Requests Pickle 错误提升暴露了相同 Frame 导致的相关错误。','困难',['Fresh Review','锚定'],'高压'),
  X('adaptivevuls','Runtime','Thin Runtime 为什么只做机械校验？','Runtime 只校验身份、版本、lineage、freshness、CAS、exactly-once 和 Gate 引用；安全语义由 Reviewer 判断。',['Runtime 能验证 exact Case Revision、stateVersion/hash、nonce、produced file、路径安全和 Artifact lineage。','它不能判断 Boundary 是否合理、Caller Misuse 是否成立、该用哪个工具或目标是否安全。','把语义写成固定 Runtime 规则会造成错误僵化；把机械一致性交给模型又会失去恢复与审计保证。'],['CAS 拒绝后怎么办？','什么是 orphan Artifact？','accepted-uncommitted 如何重放？'],'体现方法层与系统实现层的清晰分工。','困难',['Thin Runtime','CAS','Exactly-once'],'必背'),
  X('adaptivevuls','预算边界','AV 为什么不设置任何内部预算？','AV 表达的是下一次科学调查机会给谁，不表达每个 Case 分配多少分钟；时间、Token 和轮数属于外部实验 Harness。',['Investigator 不接收剩余时间、Token、固定工具数或 provisional disposition，避免围绕 deadline 扭曲科学判断。','统一外部墙钟用于公平实验；到达时只产生 operational interruption 并保存 Case/OES。','代码中的 testOnlyMaxControllerDecisions 仅用于有限 mock simulation，不属于生产方法。'],['没有内部预算如何防单点深陷？','外部停止后 Case 是什么状态？','成本还需要记录吗？'],'必须与普通 Agent budget control 区分：Harness 可观测成本，AV Packet 不暴露预算。','困难',['无内部预算','外部墙钟'],'高压'),
  X('adaptivevuls','Capability Advisor','Capability Advisor 的权限边界是什么？','它把 Evidence Obligation 映射为可能需要的 Artifact、能力和工具建议；无状态、只建议、不改 OES，也不选择 Action。',['Advice 不是 Evidence，不能自动创建 Case 或改变 Claim。','只向承担对应 Obligation 的 Case Investigator 交付，Investigator 可使用、替换或忽略。','它不能把 C/M/B/I/Own/S 固定映射成某种工具，否则会把调查方法退化为工具流水线。'],['为什么不用 Coding Agent 做 Advisor？','建议失败如何记录？','Advisor 是否访问 Canonical State？'],'V1.36 中是本地 advisory-only JavaScript sidecar。','中等',['Capability Advisor','工具建议'],'深挖'),
  X('adaptivevuls','Finding','Finding 与 Report 文本有什么区别？','Finding 是 disposition=report 且通过机械 Gate 的确定性 Case 投影；Reporter 只能读取 FindingIndex 生成文本，不能创造安全结论。',['Finding 绑定 exact Revision、Reviewed Claims、Artifact Basis、Fresh Review、Scope、target-owned Property、attacker path、incremental Impact 与 Ownership。','Report Gate 只检查这些语义是否经过合法 Review 和引用链授权，不替 Reviewer 判断文本真伪。','任何新事实或更宽 Claim 都必须回到 Case/Review，不能由 Reporter 在润色时添加。'],['FindingIndex 如何防 stale report？','Reporter 是否需要 Fresh Session？','报告修改 Scope 怎么办？'],'新简历中的“结果收口”应按确定性投影解释。','困难',['Finding','Report Gate'],'必背'),
  X('adaptivevuls','负面闭合','Negative Closure Gate 严格禁止哪些跃迁？','严格禁止 unknown→refuted、blocked/timeout→refuted，以及一个 Case 的 refutation 自动关闭整个 Frontier。',['Refuted 至少需要 scoped proposition、explicit falsifier、observed attempt、decisive Artifact、Fresh Review 与 exact identity。','Operational failure 只说明当前执行受阻，不能提供科学反证。','Closure scope 必须有界；Sibling 路径和更宽 Frontier 仍可保持开放。'],['Expected Behavior 也需要 decisive evidence 吗？','超时后如何恢复？','Frontier 何时可以关闭？'],'避免“做不出来就是不存在”的常见 Agent 错误。','困难',['Negative Closure','Refuted'],'必背')
);
;
/* Agent 工程专项：不局限于 AdaptiveVuls 方法，覆盖企业 LLM/Agent 应用岗位常见技术栈。 */
QUESTIONS.push(
  // 1. 模型 API 与应用接入
  X('agent','模型API','生产系统为什么需要 Model Gateway？','Model Gateway 在业务与不同模型 Provider 之间统一认证、协议、路由、限流、重试、成本、审计和降级，避免业务代码绑定单一厂商。',['对上提供稳定的 chat/response/embedding 接口，对下适配模型名、参数、错误码和流式事件差异。','按任务、租户、地区、成本和健康状态路由；fallback 必须考虑模型能力与数据合规，不能随意降级。','记录 Prompt/模型版本、Token、TTFT、TPOT、错误率和 request id，同时对敏感内容脱敏。'],['Gateway 会不会成为单点？','怎样做模型能力发现？','Fallback 如何保证语义兼容？'],'Workflow-Harness 的 Runner Adapter 与 Model Gateway 都使用稳定契约隔离底层差异，但一个管理完整 Coding Agent，一个管理模型调用。','中等',['Model Gateway','Provider Abstraction'],'必背'),
  X('agent','模型API','LLM 流式输出通常如何实现和处理？','服务端常通过 SSE 或分块 HTTP 持续发送 token/event；客户端增量解析、更新 UI，并在中断、取消和工具调用边界保存可恢复状态。',['事件不只有文本 delta，还可能包含 reasoning 状态、tool call 参数增量、usage、error 和完成原因。','解析器要处理 UTF-8 分片、半条 JSON、心跳、重复事件和连接中断，不能假设一次 read 是一条消息。','用户取消应向上游传播；已产生副作用的工具不能因重新请求而重复执行。'],['SSE 与 WebSocket 如何选？','流中断后能否续传？','如何统计流式 Token？'],'对应 Provider 输出、Runner stdout 与前端实时轨迹展示。','中等',['SSE','Streaming','Cancellation'],'必背'),
  X('agent','模型API','Structured Output 和 Tool Calling 有什么区别？','Structured Output 约束模型最终返回符合 Schema 的数据；Tool Calling 表达模型希望宿主执行某个动作，执行结果还要回到对话继续推理。',['抽取、分类和生成配置适合 Structured Output；查询外部事实和产生动作适合 Tool Calling。','两者都需要服务端语义校验，Schema 合法不代表 ID、权限或业务状态合法。','不要为了获取结构化答案伪造一个无副作用工具，也不要把危险副作用隐藏在普通输出解析中。'],['一个响应能否同时有文本和工具调用？','Parallel Tool Calls 有什么风险？','Schema 不兼容怎么办？'],'Reviewed Delta 是结构化提案，不是模型可直接执行的工具副作用。','简单',['Structured Output','Tool Calling'],'必背'),
  X('agent','模型API','如何做模型路由与级联调用？','先用规则或小模型判断任务复杂度、模态和风险，再选择满足能力的最低成本模型；低置信或失败时升级到更强模型。',['路由特征可以是任务类型、上下文长度、是否代码/视觉、SLA、租户和历史质量。','级联要避免同一请求被多次收费却仍无验证；升级条件需通过离线集和线上数据校准。','高风险裁决不应仅按成本降级，模型切换还要记录版本与能力差异。'],['Router 本身用模型还是规则？','如何防路由抖动？','怎样评估节省成本是否伤质量？'],'可用于 Controller、Investigator、Reviewer 的外部模型配置，但不能改变角色权限。','困难',['Model Routing','Cascade'],'深挖'),
  X('agent','模型API','Prompt 模板为什么要版本化？','Prompt 是应用行为的一部分，应像代码一样有版本、变量 Schema、测试、变更记录、灰度与回滚，避免线上悄悄漂移。',['记录 system/developer/user 片段、few-shot、工具说明和上下文组装版本，单独记录运行时数据引用。','模板变量必须转义/分隔并限制长度，防不可信内容进入高优先级指令区域。','每次修改跑固定回归集，对成功率、格式、Token、延迟和安全共同比较。'],['Prompt 应不应该存数据库？','如何做 A/B？','模型升级是否需要新 Prompt 版本？'],'阶段 Prompt、Review Package 和 Agent Skill 都应可追溯。','简单',['Prompt Management','版本化'],'必背'),
  X('agent','模型API','多模态模型接入要注意什么？','除文本外还要管理图片、音频、视频的格式、分辨率、时长、Token/费用、预处理、隐私和模型能力差异。',['图片要保留尺寸和语义顺序，OCR、图表理解和普通视觉描述是不同任务。','大图切片可提高局部细节但会丢全局关系；需要缩略图 + 局部 crop 或多尺度策略。','上传内容可能含人脸、文档密钥和隐写 Prompt Injection，需权限、脱敏与存储生命周期。'],['视觉 Token 如何估算？','OCR 与 VLM 怎么选？','图片引用如何做 Evidence？'],'未来可用于读取架构图、崩溃截图和 PDF 报告，但应把原文件作为 Artifact。','中等',['Multimodal','VLM'],'常规'),
  X('agent','模型API','LLM API 的 Rate Limit 和 Token Budget 如何工程化处理？','分别跟踪请求数、输入/输出 Token、并发和模型配额，用本地限流、队列、退避和租户预算避免集中打满 Provider。',['429 要解析 Retry-After/错误类型；指数退避加 jitter，不能所有 Worker 同时立即重试。','Prompt Token 在调用前估算并预留输出空间，超长时按语义裁剪而非从头硬截断。','预算控制属于产品/Harness 运行策略；在 AV V1.36 中不写入 Investigator 的科学 Packet。'],['TPM 与 RPM 哪个先触发？','流式调用何时计 usage？','多 Provider 配额怎么分配？'],'区分通用 Agent 平台资源治理与 AV 方法内部无预算原则。','中等',['Rate Limit','Token Accounting'],'必背'),

  // 2. 框架与编排生态
  X('agent','框架生态','LangChain 的核心抽象和适用边界是什么？','LangChain 提供模型、Prompt、Retriever、Tool、Agent 与 Runnable 组合抽象，适合快速集成；复杂长期状态通常需要更明确的图或外部工作流。',['LCEL/Runnable 用管道方式组合同步、异步、批处理和流式组件。','框架降低集成成本但也可能隐藏真实 Prompt、重试与数据流，生产中要保留可观测和可替换边界。','不要因使用 LangChain 就把业务状态存进链对象；权威状态仍应外置。'],['RunnableParallel 做什么？','AgentExecutor 和 LangGraph 如何选择？','框架升级怎么隔离？'],'可比较通用框架与自研 Workflow-Harness 的设计目标。','简单',['LangChain','LCEL'],'常规'),
  X('agent','框架生态','LangGraph 为什么适合有状态 Agent Workflow？','它用节点、边和共享 State 表达循环图，支持 checkpoint、interrupt、恢复和 human-in-the-loop，适合需要显式状态迁移的 Agent。',['节点读取状态并返回更新，Reducer 决定并发/增量字段如何合并；条件边控制下一节点。','Checkpoint 让长任务可恢复，但存储了状态不代表状态语义正确，仍要做 Schema、版本和权限校验。','图可以循环，不应把所有开放调查硬编码成固定 DAG；领域对象与控制理由仍需设计。'],['StateGraph 和 MessageGraph 区别？','Reducer 冲突怎么处理？','Checkpoint Thread ID 是什么？'],'AV 可借鉴 durable graph 能力，但其科学对象、Action Board 与 Review Gate 不是框架自动提供。','中等',['LangGraph','StateGraph','Checkpoint'],'必背'),
  X('agent','框架生态','LlamaIndex 主要解决什么？','LlamaIndex 聚焦数据连接、索引、Retriever、Query Engine 与 RAG/Agent 数据工作流，适合把多源企业数据组织成可检索上下文。',['Document/Node 表示数据与切分单元，Index/Retriever 决定如何召回，Response Synthesizer 负责基于上下文生成。','提供向量、结构化、知识图谱和路由检索，但数据治理、权限和评测仍需自行设计。','与 LangChain 有能力重叠，选型看数据/RAG 中心还是通用调用编排。'],['Query Engine 与 Retriever 区别？','Node Parser 做什么？','何时直接使用向量数据库 SDK？'],'可作为专家知识库和代码索引的候选实现层。','简单',['LlamaIndex','RAG框架'],'常规'),
  X('agent','框架生态','AutoGen 的多 Agent 对话思路是什么？','AutoGen 把 Agent 作为可对话实体，通过消息、角色、工具和群聊管理器组织协作，适合研究多 Agent 分工与交互。',['优势是快速构建角色对话和代码执行闭环；风险是对话膨胀、隐含状态和停止条件不清。','生产任务需要限制最大交接、工具权限、Workspace、消息 Schema 与最终写入者。','多个相似 Agent 的一致结论不等于独立证据。'],['GroupChat Manager 做什么？','如何终止对话？','AutoGen 和 LangGraph 如何比较？'],'可用来解释为什么 AV 不把三个主体实现成自由群聊。','中等',['AutoGen','Multi-Agent'],'常规'),
  X('agent','框架生态','CrewAI 的 Crew、Agent、Task 和 Process 如何理解？','CrewAI 以角色 Agent 执行 Task，Crew 组织团队，Process 定义顺序或层级协作，适合业务角色化自动化原型。',['角色描述有助于专业分工，但不能替代工具权限和结构化状态。','Sequential/Hierarchical 流程要处理委派、上下文传递、重复工作和结果校验。','固定角色隐喻不适合所有任务，复杂科学状态应使用领域模型而非只靠 persona。'],['CrewAI 和 AutoGen 区别？','Task Output 如何校验？','何时不该用 Crew？'],'面试中可横向比较生态，而不是声称项目依赖 CrewAI。','简单',['CrewAI','Agent Framework'],'常规'),
  X('agent','框架生态','OpenAI Agents SDK 一类轻量 Agent SDK 通常提供哪些能力？','通常提供 Agent/Instruction、Tool、Handoff、Guardrail、Session/Trace 等轻量原语，让开发者用代码组合单 Agent和多 Agent流程。',['Handoff 把控制与上下文交给另一个专门 Agent，必须限制可交接对象和传递数据。','Guardrail 可在输入、输出或工具边界做检查，但高风险权限仍需宿主强制。','SDK Trace 便于观测，但跨 Provider、长期 durable state 和复杂恢复可能需要外部平台。'],['Handoff 与 Tool Calling 区别？','Session 放什么？','SDK 和 Workflow Engine 如何配合？'],'可比较“调用模型的 Agent SDK”与“编排完整 Coding Agent Runner 的 Harness”。','中等',['Agents SDK','Handoff'],'常规'),
  X('agent','框架生态','Semantic Kernel 的 Kernel、Plugin 和 Planner 是什么思路？','Semantic Kernel 把模型服务、Prompt/原生函数封装为 Plugin，由 Kernel 管理调用与依赖，并支持规划和企业应用集成。',['Plugin 函数需要明确描述、参数 Schema 与权限，和通用 Tool 设计原则一致。','Planner/Function Choice 负责从可用能力中组合步骤，仍需状态、重试和结果校验。','其 .NET/Java/Python 生态适合企业应用，但选型应看团队语言和已有基础设施。'],['Plugin 和 MCP Tool 有何区别？','Kernel 是否保存长期状态？','为什么企业常用 Semantic Kernel？'],'用于补充主流 Agent 技术栈认知。','简单',['Semantic Kernel','Plugin'],'常规'),
  X('agent','框架生态','Google ADK 一类 Agent Development Kit 的价值是什么？','ADK 类框架用代码定义 Agent、Tool、Workflow、Session 与部署/评测集成，强调模型无关或云生态中的工程化开发。',['常提供 sequential/parallel/loop Agent、回调、Artifact 和可视化调试。','云原生集成方便但可能产生平台绑定，需隔离业务状态与 Provider 特有类型。','评估框架要做最小原型：流式、工具、恢复、Trace、权限和部署，而非只比较示例数量。'],['ADK 和 LangGraph 的控制模型区别？','怎样降低云绑定？','框架选型表应包含什么？'],'面试可表现对 Agent 生态的横向理解。','中等',['ADK','Agent Framework'],'常规'),
  X('agent','框架生态','什么时候应该自研 Agent Harness，而不是直接使用框架？','当核心差异在 Runner 会话、Workspace、恢复、审计、领域状态和协议 Gate，且通用框架无法稳定表达时，可在薄抽象上自研。',['先复用模型 SDK、MCP、存储和可观测组件，不要重写成熟的 HTTP、Tool Loop 与向量库。','自研必须说明稳定边界、测试成本、升级策略和为什么现成框架不足。','避免“Not Invented Here”；用 Adapter 把可替换生态组件隔离。'],['自研哪些层最合理？','如何证明维护成本可控？','什么时候迁回现成框架？'],'Workflow-Harness 的价值在完整 Coding Agent Runner 编排与外部状态，不是重写模型循环。','困难',['Build vs Buy','Harness'],'高压'),

  // 3. 常见 Agent Workflow Pattern
  X('agent','Workflow Pattern','Routing Pattern 是什么？','先分类输入或评估能力需求，再把请求送到专门流程、模型或工具，以降低成本并提高专业性。',['Router 可用规则、Embedding 或小模型；类别要互斥/可回退并记录置信。','错误路由会在后续被放大，因此提供 default path 和升级策略。','路由标签、模型和下游版本共同进入评测与 Trace。'],['Router 如何训练？','多标签任务怎么办？','路由错误怎么在线发现？'],'适合按仓库语言、漏洞类型或任务复杂度选择能力，但 AV Controller 不是固定分类 Router。','简单',['Routing','Workflow Pattern'],'必背'),
  X('agent','Workflow Pattern','Parallelization Pattern 什么时候有收益？','可独立子任务并行执行后聚合能降低墙钟时间或增加视角覆盖；存在依赖、共享写状态或 Provider 限流时可能更差。',['Sectioning 把不同子问题分开，Voting 对同一问题生成多个候选；两者聚合策略不同。','每个分支使用隔离上下文/Workspace，并设置 fan-out 上限和全局 deadline。','聚合器应引用每个分支证据并处理冲突，不能只拼接长文本。'],['并行数量怎么定？','多数投票何时无效？','一个分支超时怎么办？'],'Harness 通用层可并行，但 AV V1.36 科学主循环当前顺序执行。','中等',['Parallelization','Fan-out'],'必背'),
  X('agent','Workflow Pattern','Orchestrator–Worker Pattern 是什么？','Orchestrator 根据任务动态拆分子任务并委派 Worker，收集结果后综合，适合无法预先固定分解结构的复杂任务。',['Orchestrator 输出结构化 task id、依赖、输入、期望产物和停止条件。','Worker 不直接修改共享真值，只提交 Artifact/Proposal；合并检查版本和冲突。','动态委派容易递归爆炸，需要深度、并发、权限与重复任务约束。'],['和 Planner–Executor 区别？','Worker 可以再委派吗？','如何做任务去重？'],'可用于通用代码研究，但不要把 AV 三主体误写成自由委派树。','中等',['Orchestrator Worker','Delegation'],'必背'),
  X('agent','Workflow Pattern','Evaluator–Optimizer Pattern 如何工作？','一个模型生成候选，另一个基于明确标准给反馈，生成器迭代改进，适合存在清晰可评判标准的任务。',['Evaluator 需要 rubric、引用证据和通过阈值；模糊“更好”会造成无效循环。','最大迭代只是外部工程保护，最终可用确定性测试时优先测试。','生成器与评估器可能共享偏见，高风险结论需要正交数据或人工。'],['与 Reflection 区别？','何时停止？','能否用同一模型？'],'Fresh Reviewer 不是一般文案优化器，而是对 Evidence 赋予有界科学语义。','中等',['Evaluator Optimizer','Critique'],'常规'),
  X('agent','Workflow Pattern','Map–Reduce 在 LLM 应用中如何使用？','Map 阶段并行处理文档或分片，Reduce 聚合中间结果，适合长文摘要、批量抽取和仓库级分析。',['分片要保证上下文边界，Map 输出使用统一 Schema 并带来源。','Reduce 不能看到全部细节时会丢少数关键信号，可采用分层归并或证据索引。','重复信息去重、冲突处理和全局不变量需要专门步骤。'],['分片多大合适？','Reduce 上下文仍超长怎么办？','如何保留引用？'],'可用于 Security Map 初始素材处理，但 Case/Evidence 不能只靠摘要聚合。','简单',['Map Reduce','长文处理'],'常规'),
  X('agent','Workflow Pattern','State Machine 与自由 Agent Loop 如何取舍？','状态机为已知流程提供可预测合法迁移，自由 Loop 适合开放探索；生产系统常用确定性外壳包住受控 Agent 决策。',['登录、审批、支付等业务状态应确定性；研究与规划可允许模型提出下一动作。','模型输出 action proposal，Runtime 校验当前状态、权限和参数后才执行。','状态数量爆炸时用领域对象 + reducer + action board，而不是把所有组合硬编码。'],['状态机能有循环吗？','Behavior Tree 有何不同？','如何测试状态迁移？'],'AV 正是 permissive investigation + constrained canonical transition。','中等',['State Machine','Agent Loop'],'必背'),
  X('agent','Workflow Pattern','Durable Execution 对长时间 Agent 有什么价值？','把步骤、事件和副作用结果持久化，使进程崩溃、部署或等待人工后能从一致位置恢复，而不是重跑整个对话。',['每个外部副作用需要稳定 activity id 与幂等键；重放 Workflow 代码时不能重复发邮件/写数据。','状态 Schema 和 Workflow 代码要版本兼容，长运行实例可能跨越多次发布。','Temporal 类引擎提供事件历史与重试，但模型语义和 Evidence 正确性仍由应用负责。'],['Workflow Replay 为什么要求确定性？','Activity 和 Workflow 区别？','模型调用如何幂等？'],'对应 Harness crash/resume、accepted-uncommitted replay 和 exactly-once commit。','困难',['Durable Execution','Temporal','Replay'],'深挖'),
  X('agent','Workflow Pattern','Checkpoint 与 Event Sourcing 有什么区别？','Checkpoint 保存某时刻完整/增量状态以快速恢复；Event Sourcing 保存导致状态变化的事件，通过重放重建并保留完整历史。',['Checkpoint 简单快速但历史解释弱；Event log 审计强但需要事件版本、幂等和重放成本治理。','常组合使用：事件是权威历史，周期快照加速加载。','不要把未经审查的模型 Token 当领域事件；只记录合法命令、Artifact 与状态变更。'],['Reducer 如何保证确定性？','事件 Schema 怎么升级？','什么时候做 Snapshot？'],'Canonical State、Reviewed Delta 和 Action Lineage可视为受控事件化设计。','困难',['Event Sourcing','Checkpoint'],'深挖'),
  X('agent','Workflow Pattern','Interrupt / Resume 如何支持 Human-in-the-loop？','Workflow 在明确状态持久化后产生待审批中断；用户决定作为新事件写入，再从版本匹配的节点继续。',['中断包包含动作、参数、原因、风险、证据和 state version。','等待期间环境可能变化，Resume 前重验权限、资源和前置条件。','重复点击和网络重试必须幂等，审批过期后不能继续旧动作。'],['多个审批者怎么处理？','拒绝后走哪个分支？','如何撤销已开始动作？'],'适合报告发布、外部提交和高风险 PoC。','中等',['Interrupt','Resume','HITL'],'必背'),

  // 4. Advanced RAG / Knowledge System
  X('agent','Advanced RAG','Multi-Query Retrieval 为什么有效？','模型把原查询改写成多个互补表达分别召回，再去重融合，缓解单一措辞与文档用词不匹配。',['改写覆盖同义词、缩写、不同粒度和可能子问题，但要防语义漂移。','结果可用 RRF 融合，并限制 query 数量与总召回成本。','包含精确符号/CVE 的查询应保留原始关键词，不应全部改写。'],['Query Expansion 与 Decomposition 区别？','如何去重？','改写模型需要多强？'],'安全术语、函数名与自然语言问题混合时有用。','中等',['Multi-Query','Query Rewrite'],'常规'),
  X('agent','Advanced RAG','HyDE 的基本思路是什么？','先让模型生成一个假设性答案/文档，再用其 Embedding 检索真实文档，帮助短而抽象的查询进入更贴近答案的语义空间。',['HyDE 文本不是证据，只是检索查询；最终回答必须引用真实召回材料。','如果模型假设方向错误会造成检索漂移，适合和原查询/BM25 混合。','在领域术语准确、查询已很具体时收益可能有限。'],['HyDE 与 Query Rewrite 区别？','如何评测是否漂移？','生成多份假设有用吗？'],'可用于开放安全问题的资料召回，但不能把假设当 Observation。','困难',['HyDE','RAG'],'深挖'),
  X('agent','Advanced RAG','Parent–Child Retrieval 解决什么问题？','用小 Chunk 做精确向量匹配，命中后返回其更大的父段落/章节给模型，兼顾召回粒度与上下文完整性。',['Child 保存 parent id 与位置，父文档可按 Token 预算裁剪相邻内容。','如果父块过大仍会引入噪声，可配合 rerank 和 contextual compression。','代码可按函数检索、按类/调用上下文返回，是相同思想。'],['和 Small-to-Big Retrieval 区别？','父块如何定义？','一个父块多个命中怎么去重？'],'适合仓库函数级检索与文件级理解。','中等',['Parent Child Retrieval','Small-to-Big'],'常规'),
  X('agent','Advanced RAG','Contextual Compression 是什么？','在召回后根据查询提取、过滤或重写文档，只保留相关片段，降低上下文噪声与 Token。',['可用规则、高亮句、Embedding Filter、Cross-Encoder 或 LLM Extractor。','压缩必须保留来源位置并避免改变否定、条件和数值语义。','LLM 压缩成本高且可能遗漏反证，高风险证据应允许查看原文。'],['Compression 与 Summarization 区别？','如何评测信息丢失？','什么时候不应压缩？'],'Review Package 可分原始 Artifact 与查询相关视图，但原始材料保持权威。','困难',['Contextual Compression','RAG'],'深挖'),
  X('agent','Advanced RAG','Agentic RAG 与固定 RAG Pipeline 有什么区别？','Agent 根据问题决定是否检索、使用哪个数据源、如何分解与追加查询，并对结果不足进行迭代；灵活性更高但成本和不确定性增加。',['简单 FAQ 优先固定 Pipeline，减少延迟与失控；跨源复杂研究再使用 Agentic RAG。','每轮检索要记录 query、source、top-k 和停止理由，设置重复检测。','检索决策不能绕过数据权限；工具层强制 tenant/filter。'],['如何设停止条件？','Self-RAG 是什么？','检索 Agent 会不会循环？'],'Investigator 可自主取证，但 Evidence promotion 仍经 Reviewer。','困难',['Agentic RAG','Self-RAG'],'深挖'),
  X('agent','Advanced RAG','GraphRAG 适合什么问题？','GraphRAG 从文档抽取实体、关系和社区结构，支持跨文档多跳关系与全局主题查询，不是所有知识库都需要。',['构图包括实体消歧、关系抽取、来源绑定和增量更新，成本明显高于向量 RAG。','局部查询沿相关实体邻域检索，全局查询可使用社区摘要。','抽取图本身可能有幻觉，边和属性必须保留 source provenance。'],['Knowledge Graph 和 Property Graph 区别？','GraphRAG 与 Vector RAG 如何混合？','如何评测图质量？'],'国防项目知识图谱与 RAG 融合的重点知识。','困难',['GraphRAG','Knowledge Graph'],'高压'),
  X('agent','Advanced RAG','Text-to-SQL / SQL Agent 如何安全落地？','模型理解问题并生成受限 SQL，在只读、最小权限、超时和结果行数限制的环境执行，再解释结果。',['提供经过筛选的 Schema、字段语义和示例，避免把整个生产库 DDL 暴露给模型。','解析 AST 拒绝写操作、多语句、危险函数和跨租户表；数据库账号本身只读。','高成本查询先 EXPLAIN/估算，结果脱敏并记录 SQL、参数和审批。'],['如何处理用户歧义？','为什么黑名单不够？','查询结果太大怎么办？'],'Agent 平台数据分析常见落地场景。','困难',['Text-to-SQL','SQL Agent'],'必背'),

  // 5. Memory / State / Skills
  X('agent','Memory工程','短期记忆、长期记忆和 Agent State 如何区分？','短期记忆服务当前对话，长期记忆跨会话召回用户/任务知识，Agent State 是驱动 Workflow 的权威结构化状态。',['对话摘要可重建上下文但不是业务真值；订单、Case Revision 等状态必须在数据库。','长期记忆写入要有 scope、source、confidence、TTL 与删除能力。','State 更新通过命令/Reducer 校验，不能让模型自由覆盖整个 JSON。'],['Chat History 是否等于 Memory？','用户如何删除记忆？','状态和 Artifact 如何关联？'],'AV Session Memory 与 Canonical State 的区分是通用 Agent 工程最佳实践。','简单',['Short-term Memory','Agent State'],'必背'),
  X('agent','Memory工程','Memory Consolidation 如何避免无限增长？','周期性把重复事件聚类、去重并提炼为有来源的稳定事实，同时衰减低价值或过时记忆，并保留可回溯原始记录。',['写入前判断 novelty、importance 和未来可用性；不是每条对话都进长期记忆。','新事实与旧事实冲突时保存时间/版本，不直接静默覆盖。','摘要会丢细节，高风险领域保留 source refs 并允许重新验证。'],['何时触发 consolidation？','遗忘分数怎么设计？','如何防 Memory Poisoning？'],'Negative Knowledge 和 Attempt 也要有界压缩但保持 lineage。','困难',['Memory Consolidation','Forgetting'],'深挖'),
  X('agent','Memory工程','向量记忆与结构化记忆如何组合？','向量索引适合按语义找相关经历，结构化存储适合精确实体、时间、状态和约束；先过滤后相似检索通常更可靠。',['用户偏好、项目实体和任务状态存关系/文档数据库；自由文本经验建向量索引。','召回结果按时间、来源、权限和当前实体重排，不只看 cosine。','向量删除与结构化删除保持一致，防用户数据“删了但还能召回”。'],['什么时候使用知识图谱记忆？','Metadata Filter 影响 ANN 吗？','记忆冲突怎么处理？'],'适合跨 Run 复用仓库知识，但 Reviewed Evidence 仍绑定 exact Revision。','中等',['Vector Memory','Structured Memory'],'深挖'),
  X('agent','Skill工程','Agent Skill 与 Tool、Prompt、Workflow 有什么区别？','Tool 提供动作能力，Prompt 提供当前指令，Skill 封装可复用领域知识/步骤/资源，Workflow 管理跨步骤控制与持久状态。',['Skill 可以包含说明、脚本、模板和参考资料，按触发条件加载，减少每次重写复杂 Prompt。','Skill 不应假装拥有 Tool 权限；脚本执行仍受宿主安全策略。','版本化 Skill，记录适用模型/工具和测试集，防过时流程误导 Agent。'],['Skill 如何自动触发？','Skill 与 RAG 文档区别？','如何评测 Skill？'],'AV-Skill 是调查手册；AV-Enforced 额外提供 Runtime 强制。','中等',['Agent Skill','可复用能力'],'必背'),
  X('agent','协议','Agent-to-Agent 协作协议需要解决什么？','跨 Agent/平台协作需要能力发现、任务生命周期、消息/Artifact 交换、身份授权、进度、取消和结果语义，而不只是互发文本。',['任务使用稳定 ID、状态机和幂等消息；Artifact 用 URI/hash/权限引用而非塞进聊天。','能力卡描述输入输出和认证，但调用方仍需验证服务质量与数据边界。','跨组织协作要防 confused deputy、Prompt 注入和数据外泄。'],['A2A 与 MCP 区别？','任务如何取消？','远端 Agent 如何证明结果？'],'MCP 更偏工具/上下文连接，A2A 类协议更偏独立 Agent 间任务协作。','困难',['A2A','Agent Protocol'],'深挖'),

  // 6. LLMOps / Evaluation / Observability
  X('agent','LLMOps','LLM 应用的 Golden Dataset 应如何建设？','从真实流量、专家构造和故障回放中形成版本化样本，包含输入、上下文、期望行为、评分规则和重要切片。',['既包含正常问题，也包含无答案、歧义、长上下文、工具失败和对抗样本。','测试集与调优数据隔离，防反复看答案造成过拟合。','样本保存数据权限与脱敏版本；线上事故修复后加入回归集。'],['多少样本才够？','开放答案如何标注？','如何维护时间敏感答案？'],'AV 可把错误提升、stale state、Revision/Branch 等轨迹做成专项回归集。','中等',['Golden Dataset','Eval Set'],'必背'),
  X('agent','LLMOps','LLM-as-a-Judge 如何校准？','先定义具体 rubric 和输出 Schema，用人工双标样本评估 Judge 与专家一致性，再检查位置、长度、风格和自偏好。',['成对比较常比绝对分数稳定，但要随机交换候选顺序检测 position bias。','Judge 看到必要证据而非被评答案的隐藏标签，温度低并固定版本。','安全/事实关键样本保留人工或确定性判定，不能把 Judge 当 ground truth。'],['Cohen Kappa 怎么用？','不同 Judge 如何集成？','Judge 能评自己的输出吗？'],'Fresh Reviewer 是领域裁决角色，不等同通用 LLM Judge 打分。','困难',['LLM Judge','Rubric'],'深挖'),
  X('agent','LLMOps','如何评测 Tool-Using Agent 的轨迹？','除最终成功外，评测工具选择、参数正确性、调用顺序、无效/重复调用、错误恢复、证据引用和副作用安全。',['构建可控 sandbox 与 fake tools 注入超时、空结果、429、部分失败。','允许多条有效轨迹时不要硬匹配唯一序列，可验证必要里程碑和不允许动作。','统计成功成本、P50/P95 步数、Token、墙钟和人为介入。'],['轨迹越短越好吗？','如何评分并行调用？','环境错误怎么算？'],'直接适用于 Coding Agent 与 Harness Adapter 评测。','困难',['Trajectory Eval','Tool Use'],'必背'),
  X('agent','LLMOps','Agent Red Team 应覆盖哪些攻击面？','覆盖 Prompt Injection、越权工具、数据外泄、Memory Poisoning、恶意文件、资源耗尽、身份混淆和跨租户访问。',['构造直接/间接注入、嵌套编码、工具输出攻击和多步诱导，而非只测一句 jailbreak。','在无真实副作用的 sandbox 执行，观察阻断层、告警和恢复。','每个成功攻击映射到权限、数据流和业务不变量修复，加入持续回归。'],['自动生成攻击样本可靠吗？','如何衡量 Attack Success Rate？','红队与安全评测区别？'],'安全 Agent 岗位的重要交叉技术栈。','困难',['Agent Red Team','Security Eval'],'高压'),
  X('agent','LLMOps','LLM 应用可观测平台应提供什么？','把 Trace、Prompt、模型、Tool、Retriever、Token、延迟、成本、反馈和评测结果关联到一次业务 Run。',['支持按模型/Prompt/租户/版本切片，查看 TTFT、工具错误、检索命中和长尾。','采样、脱敏、访问控制和保留周期要满足隐私合规。','观测平台如 Langfuse、Phoenix 等提供通用能力，但领域状态与业务成功仍需自定义。'],['Trace 标准化难点？','如何记录 Streaming？','Prompt 内容能否全量存？'],'Harness 已有 Run/Action/Attempt，可对接 OpenTelemetry/LLMOps 平台。','中等',['Langfuse','Phoenix','LLM Observability'],'常规'),
  X('agent','LLMOps','Prompt/Model/RAG 的 CI 回归流程怎么设计？','每次 Prompt、模型、Tool Schema、Embedding 或索引策略变化触发离线评测，比较质量、安全、延迟和成本，未达阈值不发布。',['固定环境与随机参数，对非确定性任务多次采样报告置信区间。','按场景设置 blocking metric，不能用平均分掩盖高风险切片退化。','发布后 Shadow/Canary 观察真实分布，异常关联到具体版本并回滚。'],['评测多久跑一次？','模型 Provider 静默更新怎么办？','索引变化如何复现？'],'AV/Workflow 协议升级也应使用轨迹回归与 Gate 不变量测试。','中等',['Eval CI','Regression'],'必背'),
  X('agent','LLMOps','语义缓存适合什么，不适合什么？','对语义相近且答案稳定、无用户私密状态的请求可复用结果；时间敏感、权限相关和高风险回答不应盲目缓存。',['缓存键包含模型、Prompt、知识库版本、工具状态、租户和安全策略。','相似度阈值需评测，错误命中比未命中更危险；可先缓存 Embedding/检索而非最终答案。','保存 TTL、引用与失效机制，源文档更新时清除相关缓存。'],['Exact Cache 与 Semantic Cache 区别？','如何防跨用户泄露？','流式响应怎么缓存？'],'适合降低通用问答成本，不适合复用 exact Revision 的安全裁决。','困难',['Semantic Cache','Cache'],'深挖'),

  // 7. Guardrails / Sandbox / Browser & Coding Agent
  X('agent','Guardrails','LLM Guardrail 可以分哪些层？','输入层检查注入和敏感数据，模型/上下文层限制能力，工具层做权限策略，输出层校验格式与内容，运行层用沙箱限制后果。',['任何单一内容分类器都可绕过，核心副作用必须在工具/宿主层授权。','Guardrail 失败要有 fail-open/fail-closed 策略；高风险动作通常 fail-closed。','记录阻断原因与误报，持续用真实流量和红队样本调优。'],['Guardrail 与 Moderation 区别？','输出过滤能防工具滥用吗？','多语言绕过怎么办？'],'AV Runtime Gate 是状态一致性 Guard，不是通用内容安全分类器。','中等',['Guardrails','Policy Enforcement'],'必背'),
  X('agent','Guardrails','如何防止模型输出导致注入到下游系统？','把模型输出视为不可信输入，使用参数化 API、Schema 校验、编码和 allowlist，禁止直接拼接到 SQL、Shell、HTML 或配置。',['即使模型由自己系统生成，也可能受 Prompt Injection 或错误上下文影响。','SQL 使用只读账号和 AST Policy，Shell 使用 argv + sandbox，HTML 做上下文编码。','记录生成内容、校验结果和执行参数，出错时可追踪。'],['模型生成代码能直接运行吗？','JSON Schema 能防 SQL 注入吗？','怎样验证 URL？'],'Agent 把自然语言转工具参数时最基本的安全边界。','简单',['Output Validation','Injection'],'必背'),
  X('agent','隐私','LLM 应用如何处理 PII 与企业敏感数据？','先做数据分类与最小化，只向获批模型发送完成任务所需信息，结合脱敏、区域、保留策略、权限和审计。',['区分传输用于推理、Provider 日志/训练、自己 Trace 与长期 Memory 四种存储路径。','使用占位符或一致 tokenization 保留关系，必要时在可信环境回填。','用户删除和租户隔离要覆盖向量索引、缓存、日志、备份与训练数据。'],['脱敏后还能做 RAG 吗？','Provider 零保留代表什么？','Embedding 是否算敏感数据？'],'真实仓库、漏洞与厂商材料属于高敏资产。','困难',['PII','Data Governance'],'高压'),
  X('agent','Sandbox','代码执行 Agent 的 Sandbox 应具备什么？','隔离进程、文件系统、网络、资源和凭证，使用临时 Workspace、非 root、只读基础镜像、egress allowlist、cgroup 与超时。',['每个任务使用独立环境和短期凭证，结束后销毁；共享缓存只读或按内容寻址。','阻止访问宿主 socket、云元数据和内部控制面；审计 exec、文件与网络。','高风险 PoC 使用 VM/microVM 或更强内核沙箱，容器不等于绝对安全。'],['Firecracker/gVisor 有何价值？','依赖下载怎么允许？','如何保存 Artifact？'],'Workflow-Harness 运行不可信仓库与 PoC 的必备工程技术。','困难',['Sandbox','Code Execution'],'必背'),
  X('agent','Browser Agent','Browser Agent 的核心技术与难点是什么？','通过 DOM/Accessibility Tree、截图或两者结合感知页面，用浏览器自动化执行点击、输入和导航；难点是动态页面、身份、注入和不可逆动作。',['DOM 定位精确但可能被复杂组件/跨域 iframe 隐藏；视觉定位通用但坐标脆弱。','每步重新观察并确认页面状态，避免基于旧截图连续盲点；下载与弹窗需专门处理。','网页内容是不可信输入，高风险提交、支付、发送信息前需要策略与人工确认。'],['Playwright 与视觉 Computer Use 如何结合？','验证码怎么办？','如何评测浏览器任务？'],'面试中常见 Agent 落地场景，也和招聘信息自动采集相关。','中等',['Browser Agent','Playwright'],'常规'),
  X('agent','Computer Use','Computer-Use Agent 与 API Tool Agent 的区别是什么？','Computer Use 通过截图、鼠标和键盘操作任意 GUI，覆盖面广但脆弱且难验证；API Tool 结构化、可校验且更稳定。',['优先使用可用 API/DOM，GUI 作为遗留系统和无接口场景的最后手段。','使用坐标前校验窗口、分辨率和目标元素；每个动作后观察反馈。','在隔离桌面运行，限制剪贴板、文件、网络和敏感应用。'],['视觉动作如何做 grounding？','误点击怎么恢复？','如何录制可复现轨迹？'],'有助于比较 Coding Agent CLI 与通用 GUI Agent 的能力边界。','中等',['Computer Use','GUI Agent'],'常规'),
  X('agent','Coding Agent','Coding Agent 与普通 Tool-Using Agent 的工程差异是什么？','Coding Agent 面向持续变化的仓库环境，需要文件检索编辑、Shell、构建测试、Git、长会话、Workspace 隔离和 Patch 验证。',['仓库状态与命令结果是外部世界，必须保留 commit、diff、环境和 Artifact，而非只保留聊天。','编辑需要最小 diff、格式/测试和用户改动保护；并发任务使用 worktree。','构建失败要区分代码、依赖、环境与 Runner，不应盲目让模型重试。'],['为什么完整 Coding Agent 不等于模型 API Loop？','如何评测 patch？','Session Resume 有什么价值？'],'这是个人项目最需要熟练扩展的通用技术背景。','简单',['Coding Agent','Repository Agent'],'必背'),
  X('agent','Coding Agent','Repository Map / Code Index 如何帮助 Coding Agent？','用文件树、符号、引用、调用图、Embedding 和变更历史构建可按需导航的仓库视图，减少把全仓库塞进上下文。',['先用精确符号/文本搜索定位，再读取局部定义、调用者和测试；语义检索作为补充。','索引绑定 commit，文件变化后增量更新；生成代码、子模块和二进制需标记。','Map 是导航线索不是代码真值，最终结论引用原始文件与行。'],['ctags/LSP/AST 如何组合？','调用图为何不完整？','索引陈旧怎么发现？'],'适用于源码审计和大型仓库理解。','困难',['Code Index','Repository Map'],'深挖'),
  X('agent','Coding Agent','Agent 自动修改代码时如何保证 Patch 质量？','要求变更针对明确问题、保持最小范围，运行相关测试/静态检查，检查 diff 与回归，并记录未验证边界。',['修改前建立失败复现或测试，修改后验证从红到绿且正常路径不回归。','不要覆盖用户未提交改动；使用 Git status/diff 和独立 worktree。','依赖、生成文件和锁文件变化要解释；安全修复还需检查旁路与同类调用点。'],['测试全过就能合并吗？','如何防过拟合测试？','多文件 Patch 怎么 Review？'],'Case Investigator 取证可写 PoC/测试，但 Canonical Finding 不由 Patch 成功自动产生。','中等',['Patch Validation','Coding Agent'],'必背')
);

