const INTERVIEW_QUESTION_FIGURES = Object.fromEntries(INTERVIEW_FIGURES.flatMap(f=>f.questionIds.map(id=>[id,f.id])));
function interviewFigureById(id){return INTERVIEW_FIGURES.find(f=>f.id===id);}
function interviewFigureCard(f,compact=false){
  const provider=f.provider||'JavaGuide',repo=f.repo||'https://github.com/Snailclimb/JavaGuide',license=f.license||'Apache License 2.0';
  return `<figure class="guide-figure-card ${compact?'compact':''}" data-guide-id="${f.id}"><figcaption><div><span class="eyebrow">INTERVIEW GUIDE FIGURE</span><h3>${svgEsc(f.title)}</h3><p>${svgEsc(f.subtitle)}</p></div><a href="${f.source}" target="_blank" rel="noopener">${svgEsc(provider)} 原文 ↗</a></figcaption><div class="guide-image-grid ${f.images.length===1?'single':''}">${f.images.map(img=>`<button class="guide-image" data-lightbox="${img.src}" data-alt="${svgEsc(img.alt)}" aria-label="放大查看：${svgEsc(img.alt)}"><img src="${img.src}" alt="${svgEsc(img.alt)}" loading="lazy" decoding="async"/><span>${svgEsc(img.caption)}</span><i>点击放大</i></button>`).join('')}</div><div class="guide-points"><strong>面试时沿图回答</strong><ol>${f.points.map(p=>`<li>${svgEsc(p)}</li>`).join('')}</ol></div><footer>来源：<a href="${repo}" target="_blank" rel="noopener">${svgEsc(provider)}</a> · ${svgEsc(license)} · 已保留原图署名</footer></figure>`;
}

function visualById(id){ return VISUALS.find(v=>v.id===id); }
function svgEsc(s=''){ return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function svgLines(text,x,y,anchor='middle',line=15,cls='node-text'){
  const parts=String(text).split('\n');
  return `<text x="${x}" y="${y-(parts.length-1)*line/2}" text-anchor="${anchor}" class="${cls}">${parts.map((p,i)=>`<tspan x="${x}" dy="${i?line:0}">${svgEsc(p)}</tspan>`).join('')}</text>`;
}
function marker(){return `<defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 10 5 0 10z" class="arrow-fill"/></marker><filter id="soft"><feDropShadow dx="0" dy="6" stdDeviation="7" flood-opacity=".14"/></filter></defs>`;}
function node(x,y,w,h,text,color='blue'){return `<g class="svg-node ${color}" filter="url(#soft)"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12"/>${svgLines(text,x+w/2,y+h/2+5)}</g>`;}
function arrow(x1,y1,x2,y2,dash=false){return `<path d="M${x1} ${y1} L${x2} ${y2}" class="svg-arrow${dash?' dashed':''}" marker-end="url(#arrow)"/>`;}

function renderVisualSvg(v){
  const n=v.nodes, c=v.colors||[]; let body='';
  if(v.kind==='pipeline'||v.kind==='timeline'||v.kind==='sequence'){
    const w=128,g=20,start=24,y=84;
    n.forEach((x,i)=>{const px=start+i*(w+g);body+=node(px,y,w,68,x,c[i]);if(i<n.length-1)body+=arrow(px+w,y+34,px+w+g-3,y+34,v.kind==='timeline');});
    if(v.kind==='timeline') body+=`<path d="M28 178 H${Math.min(890,start+n.length*(w+g)-g)}" class="timeline-base"/>`;
  } else if(v.kind==='layers'){
    const widths=n.map((_,i)=>840-i*55);n.forEach((x,i)=>{const w=widths[i],px=(920-w)/2,py=34+i*48;body+=node(px,py,w,38,x,c[i]);});
  } else if(v.kind==='split'){
    body+=node(30,75,250,84,n[0],c[0])+arrow(280,117,330,117)+node(330,75,250,84,n[1],c[1])+arrow(580,117,630,117)+node(630,75,260,84,n[2],c[2]);
  } else if(v.kind==='loop'){
    const pos=[[350,25],[640,68],[650,170],[350,206],[60,170],[50,68]];n.forEach((x,i)=>{const [px,py]=pos[i];body+=node(px,py,220,58,x,c[i]);if(i<n.length-1){const [nx,ny]=pos[i+1];body+=arrow(px+110,py+58,nx+110,ny);}});body+=`<path d="M160 68 C150 5 440 -18 460 24" class="svg-arrow dashed" marker-end="url(#arrow)"/>`;
  } else if(v.kind==='tree'){
    body+=node(345,20,230,48,n[0],c[0]);const xs=[80,345,610];for(let i=0;i<3;i++){body+=arrow(460,68,xs[i]+115,105);body+=node(xs[i],105,230,46,n[i+1],c[i+1]);body+=arrow(xs[i]+115,151,xs[i]+115,186);body+=node(xs[i],186,230,46,n[i+4],c[i+4]);if(i<2)body+=arrow(xs[i]+230,209,xs[i+1]-4,209,true);}
  } else if(v.kind==='versions'){
    body+=node(40,50,175,62,n[0],c[0])+arrow(215,81,270,81)+node(270,50,175,62,n[1],c[1])+arrow(445,81,500,81)+node(500,50,175,62,n[2],c[2]);body+=node(170,170,220,60,n[3],c[3])+arrow(390,200,555,200)+node(555,170,220,60,n[4],c[4]);body+=`<path d="M280 170 C300 125 520 125 585 170" class="svg-arrow dashed" marker-end="url(#arrow)"/>`;
  } else if(v.kind==='memory'){
    const w=150,g=25;n.forEach((x,i)=>{const px=22+i*(w+g);body+=node(px,64,w,72,x,c[i]);if(i<n.length-1)body+=arrow(px+w,100,px+w+g-3,100);body+=`<text x="${px+w/2}" y="160" text-anchor="middle" class="step-text">t${i+1}</text>`;});body+=`<path d="M30 182 H880" class="timeline-base"/>`;
  } else if(v.kind==='radial'){
    body+=node(350,94,220,68,n[0],c[0]);const pos=[[40,25],[660,25],[40,190],[660,190],[350,218]];for(let i=1;i<n.length;i++){const [px,py]=pos[i-1];body+=node(px,py,220,55,n[i],c[i]);body+=arrow(460,128,px+110,py+27,true);}
  }
  return `<svg class="knowledge-svg" viewBox="0 0 920 280" role="img" aria-label="${svgEsc(v.title)}"><title>${svgEsc(v.title)}</title>${marker()}${body}</svg>`;
}
function visualCard(v,compact=false){return `<figure class="visual-card ${compact?'compact':''}" data-visual-id="${v.id}"><figcaption><span class="eyebrow">VISUAL EXPLAINER</span><h3>${svgEsc(v.title)}</h3><p>${svgEsc(v.subtitle)}</p></figcaption><div class="svg-wrap">${renderVisualSvg(v)}</div><div class="visual-note"><strong>怎么看这张图</strong><p>${svgEsc(v.explain)}</p></div></figure>`;}
;
